mapper.select:
    	SELECT id, nombre, email, password, juego_id AS juegoId, icono_id AS iconoId, emblema_1_id AS emblema1Id, emblema_2_id AS emblema2Id, emblema_3_id AS emblema3Id
    	FROM Usuario


	            AND id = #{id}


	            AND nombre = #{nombre}


	            AND email = #{email}


	            AND password = #{password}


	            AND juego_id = #{juegoId}


	            AND icono_id = #{iconoId}


	            AND emblema_1_id = #{emblema1Id}


	            AND emblema_2_id = #{emblema2Id}


	            AND emblema_3_id = #{emblema3Id}
